function pickNumericFile(recordId){
 const input=document.createElement('input');input.type='file';input.accept='.xlsx,.xls,.csv';
 input.addEventListener('change',()=>{const file=input.files?.[0];if(file)void uploadNumeric(recordId,file);});
 input.click();
}
// 上传：recordId 为 'page' 或空时，用文件名自动新建一条记录。
async function uploadNumeric(recordId,file){
 const p=project();
 if(!numericFileRe.test(file.name))return toast('只支持 .xlsx / .xls / .csv 文件。');
 if(file.size>20*1024*1024)return toast('文件超过 20 MB，无法放进项目。');
 let target=recordId&&recordId!=='page'?p.numerics.find(n=>n.id===recordId):null;
 try{
  if(!target){
   target={id:uid(),title:file.name.replace(numericFileRe,'')||'数值表',file:'',notes:'',size:0,updated:today()};
   p.numerics.unshift(target);persist();
   if(!await disk.flush())throw new Error('记录保存失败，请重试。');
  }
  const body=await file.arrayBuffer();
  const response=await fetch(`/api/projects/${p.id}/numerics`,{method:'POST',headers:{'x-record-id':target.id,'x-file-name':encodeURIComponent(file.name),'Content-Type':'application/octet-stream'},body});
  const result=await response.json().catch(()=>({}));
  if(!response.ok)throw new Error(result.error||'上传失败。');
  target.file=result.file;target.size=result.size;target.updated=today();
  activity(`上传了数值表「${target.title}」`,'numerics',target.id);
  persist();render();
  await savedToast(`已上传「${result.file}」，点卡片可以写备注。`);
 }catch(error){toast('上传数值表失败：'+error.message);render();}
}
async function previewNumeric(recordId){
 const p=project();numericSel=recordId;
 try{numericData=await api(`/api/projects/${p.id}/numerics/${recordId}/preview`);}catch(error){toast('无法预览：'+error.message);return;}
 numericSheet=0;renderNumericPreview();
}
function renderNumericPreview(){
 const p=project(),n=p.numerics.find(x=>x.id===numericSel);if(!n||!numericData)return;
 if(numericData.unsupported){modal(`${n.title} · 预览`,`<div class="empty">${esc(numericData.unsupported)}</div>`,`<button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-numeric-open="${n.id}">用本地 Excel 打开</button>`);return;}
 const sheets=numericData.sheets||[],sheet=sheets[numericSheet]||{rows:[],name:''};
 const tabs=sheets.length>1?`<div class="tabs sheet-tabs">${sheets.map((s,i)=>`<button class="tab ${i===numericSheet?'selected':''}" data-numeric-sheet="${i}">${esc(s.name)}</button>`).join('')}</div>`:'';
 const table=sheet.rows.length?`<div class="sheet-wrap"><table class="sheet-table">${sheet.rows.map((row,ri)=>`<tr>${row.map(cell=>`<${ri?'td':'th'}>${esc(cell)}</${ri?'td':'th'}>`).join('')}</tr>`).join('')}</table></div>`:'<div class="empty">这张表没有内容。</div>';
 modal(`${n.title} · 预览`,tabs+table+(sheet.truncated?'<p class="sheet-note">内容较多，只显示前 400 行 / 60 列；完整数据请用本地 Excel 打开。</p>':''),`<button class="btn" data-action="close-modal">关闭</button><button class="btn primary" data-numeric-open="${n.id}">用本地 Excel 打开</button>`,'wide');
}
