document.addEventListener('submit',async e=>{if(e.target.id==='record-form'){e.preventDefault();const form=e.target,type=form.dataset.type,id=form.dataset.id,data=Object.fromEntries(new FormData(form));if(type==='stories'){data.characters=[...form.querySelectorAll('[name="characters"]:checked')].map(i=>i.value);data.type=data.type||'主线';data.content=data.content||'';}data.title=data.title.trim();if(!data.title)return toast('请填写名称。');if((type==='tasks'||type==='bugs')&&!data.due)return toast('请选择截止日期。');if((type==='logs'||type==='milestones')&&!data.date)return toast('请选择日期。');if(type==='assets'&&data.url&&!safeURL(data.url))return toast('请输入 http:// 或 https:// 开头的链接。');const list=project()[type];if(id){const item=list.find(x=>x.id===id);Object.assign(item,data,{updated:today()});}else list.unshift({...data,id:uid(),updated:today(),...(type==='tasks'?{number:Math.max(0,...list.map(t=>t.number||0))+1}:{}),...(type==='numerics'?{file:'',size:0}:{})});const item=id?list.find(x=>x.id===id):list[0];if(type==='characters'){const sel=[...form.querySelectorAll('[name="appearances"]:checked')].map(i=>i.value);for(const st of project().stories){st.characters=Array.isArray(st.characters)?st.characters:[];const has=st.characters.includes(item.id),want=sel.includes(st.id);if(want&&!has){st.characters.push(item.id);st.updated=today();}if(!want&&has){st.characters=st.characters.filter(c=>c!==item.id);st.updated=today();}}}activity(`${id?'更新':'创建'}了「${item.title}」`,type,item.id);closeModal();await savedToast('已写入 Project。');}
 if(e.target.id==='project-form'){e.preventDefault();const form=e.target,data=Object.fromEntries(new FormData(form));data.name=data.name.trim();if(!data.name)return toast('请填写项目名称。');const id=form.dataset.id;if(id){Object.assign(state.projects.find(p=>p.id===id),data);}else{const p=makeProject(data.name,data.genre,data.engine,data.desc);Object.assign(p,data);state.projects.push(p);state.active=null;page='library';libraryDeleted=false;libraryQuery='';}persist();rememberActive();closeModal();await savedToast(id?'项目资料已写入 Project。':'新项目已在 Project 中创建。');}});
document.addEventListener('input',e=>{const el=e.target;if(taskEditor&&el.dataset.taskField){taskEditor.draft[el.dataset.taskField]=el.value;}if(taskEditor&&el.dataset.acceptanceText){const a=taskEditor.draft.acceptance.find(x=>x.id===el.dataset.acceptanceText);if(a)a.text=el.value;}if(taskEditor&&el.dataset.acceptanceDesc){const a=taskEditor.draft.acceptance.find(x=>x.id===el.dataset.acceptanceDesc);if(a)a.desc=el.value;}if(el.id==='library-search'){const cursor=el.selectionStart;libraryQuery=el.value;renderLibrary();const input=$('#library-search');input.focus();if(input.type!=='search')input.setSelectionRange(cursor,cursor);}
if(el.id==='task-search'){const cursor=el.selectionStart;taskFilter=el.value;render();$('#task-search').focus();$('#task-search').setSelectionRange(cursor,cursor);}if(el.id==='record-search'){const cursor=el.selectionStart;recordFilter=el.value;render();$('#record-search').focus();$('#record-search').setSelectionRange(cursor,cursor);}if(el.id==='global-search')runSearch(el.value);if(el.id==='doc-title'){editor.doc.title=el.value;autoSaveEditor();}if(el.id==='doc-version'){editor.doc.version=el.value.slice(0,20);autoSaveEditor();}if(el.id==='doc-content'&&!composer&&editor){editor.doc.content=el.value;autoSaveEditor();}if(el.id==='diagram-source'){const g=activeDiagram();g.source=el.value;autoSaveEditor();clearTimeout(previewTimer);previewTimer=setTimeout(()=>renderDiagram(g,'diagram-preview'),500);}if(el.id==='diagram-name'){const g=activeDiagram();g.title=el.value;const option=$('#diagram-picker option:checked');if(option)option.textContent=el.value;autoSaveEditor();}});
document.addEventListener('change',e=>{const el=e.target;if(taskEditor&&el.dataset.taskField){taskEditor.draft[el.dataset.taskField]=el.value;}if(el.id==='task-category'){taskCategory=el.value;render();}if(el.dataset.taskStatus)setStatus('tasks',el.dataset.taskStatus,el.value);if(el.dataset.bugStatus)setStatus('bugs',el.dataset.bugStatus,el.value);if(el.id==='diagram-picker'){editor.activeDiagram=el.value;renderEditor();}if(el.id==='import-file'){importBackup(el.files[0]);el.value='';}});
document.addEventListener('paste',e=>{if(!taskEditor)return;if(!e.target?.closest?.('.task-panel'))return;const files=[...(e.clipboardData?.files||[])].filter(f=>String(f.type||'').startsWith('image/'));if(!files.length)return;e.preventDefault();const target=imageTargetFrom(e.target);for(const file of files)void uploadTaskImage(file,target);});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!e.defaultPrevented){e.preventDefault();if(page==='library'){$('#library-search')?.focus();return;}if(editor)dismissEditor();searchModal();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&editor){e.preventDefault();saveEditor();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&taskEditor){e.preventDefault();void saveTask();}if(e.key==='Escape'&&!e.defaultPrevented){const light=$('.image-lightbox');if(light){light.remove();return;}if($('#modal-root').children.length)closeModal();else if(editor)closeDocument();else if(taskEditor)closeTaskPanel();}if(e.key==='Tab'&&e.target.id==='diagram-source'){e.preventDefault();const el=e.target,start=el.selectionStart,end=el.selectionEnd;el.setRangeText('  ',start,end,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag]');if(card)e.dataTransfer.setData('text/plain',card.dataset.drag);});
document.addEventListener('dragover',e=>{const nz=e.target.closest('[data-numeric-drop]');if(nz){if([...(e.dataTransfer?.types||[])].includes('Files')){e.preventDefault();nz.classList.add('drop-active');}return;}const col=e.target.closest('[data-drop]');if(col){e.preventDefault();col.classList.add('drop-active');}});
document.addEventListener('dragleave',e=>{const nz=e.target.closest('[data-numeric-drop]');if(nz&&!nz.contains(e.relatedTarget))nz.classList.remove('drop-active');const col=e.target.closest('[data-drop]');if(col&&!col.contains(e.relatedTarget))col.classList.remove('drop-active');});
document.addEventListener('drop',e=>{const nz=e.target.closest('[data-numeric-drop]');if(nz){e.preventDefault();nz.classList.remove('drop-active');const file=[...(e.dataTransfer?.files||[])][0];if(file)void uploadNumeric(nz.dataset.numericDrop,file);return;}const col=e.target.closest('[data-drop]');if(col){e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(project().tasks.some(t=>t.id===id))setStatus('tasks',id,col.dataset.drop);col.classList.remove('drop-active');}});
function diskLabel(){return diskPhase==='error'?'Project 保存失败 · 修改尚未写入':diskPhase==='saved'?'已保存到 Project':diskPhase==='loading'?'正在读取 Project':'正在保存到 Project…';}
function storageNotice(phase,error){diskPhase=phase;storageError=phase==='error';$$('.disk-status,.saved-time').forEach(el=>el.textContent=diskLabel());const notice=$('#disk-notice');if(!notice)return;notice.innerHTML=error?`<section class="disk-error"><strong>Project 保存未完成</strong><p>${esc(error.message)}</p>${error.conflicts?.length?`<pre>${esc(error.conflicts.slice(0,10).join('\n'))}</pre>`:''}<div class="settings-actions">${button('重试保存','retry-save','check')}${button('导出待保存备份','export','download')}${button('读取磁盘版本','reload-disk','folder')}</div></section>`:'';}
function rememberActive(){try{sessionStorage.setItem('gameforge-active-project',state.active||'');}catch{}}
function readLegacy(){try{const data=JSON.parse(localStorage.getItem(LEGACY_STORAGE));return validBackup(data)&&data.projects.length?data:null;}catch{return null;}}
async function savedToast(message){const ok=await disk.flush();toast(ok?message:'修改尚未写入 Project，请查看保存提示。');return ok;}
async function initializeWorkspace(){
 $('#app').innerHTML='<div class="startup"><h1>正在读取 Project…</h1><p>从工作台目录加载游戏项目。</p></div>';
 try{
  state=await disk.load();legacyData=readLegacy();
  if(!state.projects.length){
   if(legacyData){await api('/api/migrate-browser','POST',{state:legacyData});state=await disk.load();toast('旧版浏览器内容已迁移到 Project，原浏览器副本仍保留。');}
  }
  state.active=null;page='library';render();
 }catch(error){storageNotice('error',error);$('#app').innerHTML=`<div class="startup"><h1>暂时无法读取 Project</h1><p>${esc(error.message)}</p><p>项目文件不会被示例数据覆盖。请保持服务开启，并检查 Project 文件及版本控制冲突。</p>${button('重新读取','retry-load','folder',true)}</div>`;}
}
async function reloadProjectFiles(recover=false){
 try{
  if(editor){clearTimeout(saveTimer);editor.doc.title=editor.doc.title.trim()||'未命名策划文档';persist();}
  if(disk.dirty&&!recover&&!await disk.flush()){
   modal('磁盘文件已有更新',`<p class="notice">你的待保存修改仍在页面中。重新载入前，会将它们保存为 .workbench/recovery 下的 JSON 恢复副本；磁盘上其他人的内容会保留。也可以先导出备份，继续手动合并。</p>`,`<button class="btn" data-action="export">导出待保存备份</button><button class="btn primary" data-action="recover-reload">保留恢复副本并载入</button>`);return;
  }
  if(recover){const result=await api('/api/recovery','POST',{state});toast('待保存修改已备份到 '+result.file);}
  const active=state.active,next=await disk.load();dismissEditor();clearTimeout(saveTimer);clearTimeout(previewTimer);state=next;state.active=next.projects.some(p=>p.id===active&&!p.deletedAt)?active:null;if(!state.active)page='library';$('#modal-root').innerHTML='';$('#app').inert=false;render();if(!recover)toast('已读取 Project 最新文件。');
 }catch(error){storageNotice('error',error);toast(error.message);}
}
async function migrateBrowser(){try{if(!legacyData)return toast('当前浏览器没有旧版项目。');if(disk.dirty&&!await disk.flush())return;const result=await api('/api/migrate-browser','POST',{state:legacyData});await reloadProjectFiles();toast(result.alreadyMigrated?'这份浏览器数据已经迁移过，未重复添加。':'旧版内容已迁移到 Project，现有项目已保留。');}catch(error){storageNotice('error',error);}}
function renderEmptyWorkspace(){page='library';renderLibrary();}
function renderLibrary(){document.title=BRAND+' · 项目库';$('#app').innerHTML=libraryMarkup({state,query:libraryQuery,deleted:libraryDeleted,status:diskLabel(),icon,projectInfo:disk.projectInfo,issues:disk.issues});}
function enterProject(id){if(editor)dismissEditor();const p=state.projects.find(p=>p.id===id&&!p.deletedAt);if(!p)return toast('此项目已被删除，请重新读取项目库。');state.active=id;page='overview';taskFilter='';recordFilter='';taskTab='progress';docTab='all';rememberActive();$('#modal-root').innerHTML='';$('#app').inert=false;render();window.scrollTo(0,0);}
function renameProject(id){const p=state.projects.find(p=>p.id===id&&!p.deletedAt);if(!p)return;modal('重命名项目',`<form id="project-form" data-id="${p.id}">${field('name','项目名称',p.name)}<p class="form-help">名称会更新到项目资料，文件夹 ID 保持不变。</p></form>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn primary" form="project-form" type="submit">保存名称</button>`);}
function confirmDeleteProject(id){const p=state.projects.find(p=>p.id===id&&!p.deletedAt);if(!p)return;modal('删除项目',`<div class="project-delete-message"><span>${icon('folder')}</span><h3>${esc(p.name)}</h3><p>此项目将从项目库移入回收站。任务、文档和图表会完整保留，之后可以恢复。</p><small>删除状态会写入 Project，可通过 Git / SVN 同步。</small></div>`,`<button class="btn" data-action="close-modal">保留项目</button><button class="btn danger" data-action="confirm-delete-project" data-id="${p.id}">删除项目</button>`);}
async function deleteProjectFromLibrary(id){try{markProjectDeleted(state,id);page='library';persist();closeModal();await savedToast('项目已移入项目回收站。');}catch(error){toast(error.message);}}
async function restoreLibraryProject(id){try{const p=restoreProject(state,id);persist();renderLibrary();await savedToast(`已恢复项目「${p.name}」。`);}catch(error){toast(error.message);}}
function confirmPurgeTrash(){
 const trash=state.projects.filter(p=>p.deletedAt);
 if(!trash.length)return toast('回收站已经是空的。');
 const shown=trash.map(p=>{const info=disk.projectInfo[p.id]||{};return `<li>${esc(p.name)}${info.external&&info.directory?`<small>${esc(info.directory)}</small>`:''}</li>`;}).join('');
 modal('清空回收站',`<div class="project-delete-message"><span>${icon('close')}</span><h3>${trash.length} 个项目将被彻底删除</h3><p><strong>此操作不可恢复。</strong>每个项目都会从磁盘删除它自己的文件夹，任务、文档、图表、图片附件和回收站内容都会一并消失。</p><ul class="purge-list">${shown}</ul><small>外部关联项目（关联文件夹 / 链接导入）会连同它关联的那个文件夹一起删掉，文件夹里属于你自己的其它文件也会消失。</small></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn danger" data-action="confirm-purge-trash">彻底删除 ${trash.length} 个项目</button>`);
}
let purgeBusy=false;
async function purgeTrash(){
 if(purgeBusy)return;
 const ids=state.projects.filter(p=>p.deletedAt).map(p=>p.id);
 if(!ids.length){closeModal();renderLibrary();return toast('回收站已经是空的。');}
 const confirmButton=$('[data-action="confirm-purge-trash"]'),label=confirmButton?.textContent;
 purgeBusy=true;if(confirmButton){confirmButton.disabled=true;confirmButton.textContent='正在删除…';}
 try{
  if(disk.dirty&&!await disk.flush())throw new Error('当前修改尚未保存到 Project，已停止清空操作。请先处理保存提示后重试。');
  const {state:next,result}=await disk.purge(ids);state=next;closeModal();page='library';renderLibrary();
  const removed=(result?.purged||0)+(result?.skipped||0),warning=result?.warnings?.length?`；${result.warnings.length} 个临时目录未能完全删除`:'';
  toast(`已彻底删除 ${removed||ids.length} 个回收站项目${result?.detached?`，解除 ${result.detached} 个外部关联`:''}${warning}。`);
 }catch(error){toast('清空回收站未完成：'+error.message+'。页面保留原项目，可重试。');}
 finally{purgeBusy=false;if(confirmButton){confirmButton.disabled=false;confirmButton.textContent=label;}}
}
function confirmPurgeProject(id){
 const p=state.projects.find(q=>q.id===id&&q.deletedAt);
 if(!p)return;
 const info=disk.projectInfo[id]||{};
 const external=Boolean(info.external);
 const detail=external?`会从磁盘删除它关联的项目文件夹${info.directory?` ${esc(info.directory)}`:''}，任务、文档、图表、图片附件和回收站内容都会一并消失`:'会从磁盘删除整个项目文件夹，任务、文档、图表、图片附件和回收站内容都会一并消失';
 modal('彻底删除项目',`<div class="project-delete-message"><span>${icon('close')}</span><h3>${esc(p.name)}</h3><p><strong>此操作不可恢复。</strong>${detail}。</p><small>${external?`外部关联项目位于 ${esc(info.directory||'你的磁盘目录')}，这个文件夹里的所有内容（包括你自己放进去的文件）都会一起消失，也不受 Git / SVN 同步保护。`:`内部项目位于 Project/${esc(p.id)}，删除后不受 Git / SVN 同步保护。`}</small></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn danger" data-action="confirm-purge-project" data-id="${p.id}">彻底删除</button>`);
}
async function purgeProject(id){
 if(purgeBusy)return;
 const p=state.projects.find(q=>q.id===id&&q.deletedAt);
 if(!p)return toast('此项目已不在回收站中。');
 const confirmButton=$('[data-action="confirm-purge-project"]'),label=confirmButton?.textContent;
 purgeBusy=true;if(confirmButton){confirmButton.disabled=true;confirmButton.textContent='正在删除…';}
 try{
  if(disk.dirty&&!await disk.flush())throw new Error('当前修改尚未保存到 Project，已停止删除操作。请先处理保存提示后重试。');
  const {state:next}=await disk.purge([id]);state=next;closeModal();page='library';renderLibrary();
  toast(`已彻底删除项目「${p.name}」`);
 }catch(error){toast('彻底删除未完成：'+error.message+'。页面保留原项目，可重试。');}
 finally{purgeBusy=false;if(confirmButton){confirmButton.disabled=false;confirmButton.textContent=label;}}
}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.openProject)enterProject(el.dataset.openProject);if(el.dataset.renameProject)renameProject(el.dataset.renameProject);if(el.dataset.deleteProject)confirmDeleteProject(el.dataset.deleteProject);if(el.dataset.restoreProject)void restoreLibraryProject(el.dataset.restoreProject);if(el.dataset.purgeProject)confirmPurgeProject(el.dataset.purgeProject);if(el.dataset.libraryTab){libraryDeleted=el.dataset.libraryTab==='deleted';libraryQuery='';renderLibrary();}});
function recycle(type,id){const p=project(),index=p[type].findIndex(r=>r.id===id);if(index<0)return;if(editor)dismissEditor();const [record]=p[type].splice(index,1);p.trash??=[];p.trash.unshift({id:uid(),type,record,index,date:today()});persist();closeModal();void savedToast('内容已移入项目回收站，可在工作台设置中恢复。');}
// 记录卡片上的“删除”角标：彻底删除，连同磁盘文件，不可恢复。
function cardDelete(type,id){return `<button class="card-delete" data-purge="${type}" data-id="${id}" title="彻底删除（连同文件，不可恢复）" aria-label="彻底删除">${icon('close')}</button>`;}
const recordTypeLabel={tasks:'任务',docs:'文档',world:'世界设定',characters:'角色',assets:'资源',bugs:'问题',logs:'开发日志',milestones:'里程碑',stories:'故事',numerics:'数值表'};
function confirmPurgeRecord(type,id){const p=project(),r=p[type]?.find(x=>x.id===id);if(!r)return;const label=recordTypeLabel[type]||'内容';const fileNote=type==='docs'?'，连同正文、图表和图片的整个文件夹':type==='numerics'?'，连同上传的 Excel 文件':'以及对应的文件';modal('彻底删除'+label,`<div class="project-delete-message"><span>${icon('close')}</span><h3>${esc(r.title)}</h3><p><strong>此操作不可恢复。</strong>将从项目中彻底删除这条${label}${fileNote}，删除后无法找回。</p><small>删除会写入 Project，可通过 Git / SVN 同步。</small></div>`,`<button class="btn" data-action="close-modal">取消</button><button class="btn danger" data-action="confirm-purge-record" data-type="${type}" data-id="${id}">彻底删除</button>`);}
async function purgeRecord(type,id){
 const p=project(),index=p[type]?.findIndex(r=>r.id===id);if(index<0)return;
 const title=p[type][index].title;
 const button=$('[data-action="confirm-purge-record"]'),label=button?.textContent;
 if(button){button.disabled=true;button.textContent='正在删除…';}
 try{
  if(type==='docs'&&editor?.doc?.id===id)dismissEditor();
  p[type].splice(index,1);
  closeModal();persist();
  const ok=await disk.flush();if(!ok)throw new Error('保存到 Project 失败，请重试。');
  // 普通记录的文件由差分保存自动删除；文档正文/图表也已随之删除，这里再清理整个目录（含图片）。
  // 旧版本服务可能没有该接口：此时主体已删干净，仅图片目录可能残留，重启工作台后可彻底清理。
  let deepClean=true;
  if(type==='docs'||type==='numerics'){try{await api(`/api/projects/${p.id}/records/${type}/${id}/purge`,'POST',{});}catch(error){deepClean=false;}}
  render();toast(deepClean?`已彻底删除「${title}」及其文件。`:`已删除「${title}」，重启工作台后可彻底清理残留图片。`);
 }catch(error){toast('彻底删除未完成：'+error.message+'。请重试。');}
 finally{if(button){button.disabled=false;button.textContent=label;}}
}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.purge){confirmPurgeRecord(el.dataset.purge,el.dataset.id);return;}if(el.dataset.recycle)recycle(el.dataset.recycle,el.dataset.id);if(el.dataset.restore){const p=project(),i=p.trash?.findIndex(r=>r.id===el.dataset.restore);if(i>=0){const item=p.trash.splice(i,1)[0];p[item.type].splice(Math.min(item.index,p[item.type].length),0,item.record);persist();render();void savedToast('内容已恢复到 Project。');}}if(el.dataset.zoom){const svg=$('#diagram-preview svg');if(!svg)return;if(el.dataset.zoom==='fit'){svg.style.width='';svg.style.maxWidth='100%';svg.style.maxHeight='45vh';}else{const width=svg.getBoundingClientRect().width*(el.dataset.zoom==='in'?1.25:.8);svg.style.maxWidth='none';svg.style.maxHeight='none';svg.style.width=Math.min(3000,Math.max(120,width))+'px';}}});
window.addEventListener('beforeunload',e=>{composer?.flushBlocks();diagramComposer?.flush();if(editor?.dirty){clearTimeout(saveTimer);editor.doc.title=editor.doc.title.trim()||'未命名策划文档';persist();}if(disk.dirty||composer?.pendingImages){void disk.flush();e.preventDefault();e.returnValue='';}});
const docCtx=()=>({project,esc,icon,tag,dateLabel,modal,closeModal,toast,persist,render,openDoc,uid,today});
function mountDocViews(){if(page==='docs')mountDocStructure(docCtx());}
setupRepositoryUI({getState:()=>state,disk,modal,field,button,icon,toast,esc,reload:reloadProjectFiles});
setupUpdateUI({api,modal,button,icon,disk,toast});
setupDocStructure(docCtx());
void initializeWorkspace();

document.addEventListener('click',event=>{if(!composer?.pendingImages||event.target.closest('#doc-composer')||event.target.closest('[data-action=save-doc]'))return;const action=event.target.closest('button,a,[data-action]');if(action){event.preventDefault();event.stopImmediatePropagation();toast('图片正在插入，请稍候。');}},true);

